import { boolean, char, datetime, index, json, mysqlEnum, mysqlTable, primaryKey, smallint, text, uniqueIndex, varchar } from 'drizzle-orm/mysql-core';
import {
  EVENT_CATEGORIES,
  EVENT_TYPES,
  INCIDENT_ORIGINS,
  INCIDENT_STATUSES,
  INVESTIGATION_STATUSES,
  SEVERITIES,
  type DetectionDefinitionV1,
  type EventBodyV1,
} from '@aegis/domain';

/**
 * Drizzle schema — source for versioned migrations in `apps/api/drizzle`
 * (`npm run db:generate`). IDs are UUIDv4 generated by the domain; timestamps
 * are written by the domain in UTC with millisecond precision.
 */

const timestamps = {
  createdAt: datetime('created_at', { mode: 'date', fsp: 3 }).notNull(),
  updatedAt: datetime('updated_at', { mode: 'date', fsp: 3 }).notNull(),
};

export const users = mysqlTable('users', {
  id: char('id', { length: 36 }).primaryKey(),
  name: varchar('name', { length: 120 }).notNull(),
  email: varchar('email', { length: 254 }).notNull().unique('users_email_unique'),
  /** 11 digits, no separators. */
  cpf: char('cpf', { length: 11 }).notNull().unique('users_cpf_unique'),
  passwordHash: varchar('password_hash', { length: 255 }).notNull(),
  ...timestamps,
});

export const workspaces = mysqlTable('workspaces', {
  id: char('id', { length: 36 }).primaryKey(),
  name: varchar('name', { length: 150 }).notNull(),
  kind: mysqlEnum('kind', ['personal', 'demo', 'organization', 'lab']).notNull(),
  ...timestamps,
});

export const memberships = mysqlTable(
  'memberships',
  {
    userId: char('user_id', { length: 36 })
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    role: mysqlEnum('role', ['OWNER', 'ADMIN', 'ANALYST', 'VIEWER']).notNull(),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    // One membership per (user, workspace): the composite key forbids duplicates.
    primaryKey({ name: 'memberships_user_workspace_pk', columns: [table.userId, table.workspaceId] }),
    index('memberships_workspace_idx').on(table.workspaceId),
  ],
);

/**
 * Machines registered in a workspace. `display_name`/`description` are
 * administrative (user-edited); the remaining nullable columns and
 * `connection_state` are reserved for the future Aegis Collector.
 */
export const hosts = mysqlTable(
  'hosts',
  {
    id: char('id', { length: 36 }).primaryKey(),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    displayName: varchar('display_name', { length: 120 }).notNull(),
    description: varchar('description', { length: 500 }),
    // UNIQUE allows many NULLs in MySQL: unique only once a collector is paired.
    agentId: char('agent_id', { length: 36 }).unique('hosts_agent_id_unique'),
    hostname: varchar('hostname', { length: 255 }),
    osName: varchar('os_name', { length: 100 }),
    osVersion: varchar('os_version', { length: 100 }),
    architecture: varchar('architecture', { length: 32 }),
    connectionState: mysqlEnum('connection_state', ['UNPAIRED', 'ONLINE', 'OFFLINE']).notNull().default('UNPAIRED'),
    lastSeenAt: datetime('last_seen_at', { mode: 'date', fsp: 3 }),
    ...timestamps,
  },
  (table) => [
    // Serves the workspace FK and the paginated list (WHERE workspace_id = ? ORDER BY created_at DESC, id DESC).
    index('hosts_workspace_created_idx').on(table.workspaceId, table.createdAt, table.id),
  ],
);

/**
 * Declarative detection rules (schema v1, ADR-022). `definition` is validated
 * JSON data — never code. Rules are configuration only: nothing evaluates them yet.
 */
export const detectionRules = mysqlTable(
  'detection_rules',
  {
    id: char('id', { length: 36 }).primaryKey(),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    name: varchar('name', { length: 120 }).notNull(),
    description: varchar('description', { length: 1000 }),
    severity: mysqlEnum('severity', ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL']).notNull(),
    enabled: boolean('enabled').notNull().default(true),
    eventCategory: mysqlEnum('event_category', ['PROCESS', 'NETWORK', 'SYSTEM']).notNull(),
    scope: mysqlEnum('scope', ['ALL_HOSTS', 'SELECTED_HOSTS']).notNull(),
    definition: json('definition').$type<DetectionDefinitionV1>().notNull(),
    ...timestamps,
  },
  (table) => [
    // Serves the workspace FK and the paginated list (WHERE workspace_id = ? ORDER BY created_at DESC, id DESC).
    index('detection_rules_workspace_created_idx').on(table.workspaceId, table.createdAt, table.id),
  ],
);

/**
 * Rule ↔ Host targets for SELECTED_HOSTS rules. Deleting a rule cascades to
 * its targets; deleting a targeted host is restricted (the application answers
 * 409) so a SELECTED_HOSTS rule never silently loses its last target.
 * Same-workspace consistency is enforced by the application inside the same
 * transaction that writes the targets.
 */
export const detectionRuleTargets = mysqlTable(
  'detection_rule_targets',
  {
    detectionRuleId: char('detection_rule_id', { length: 36 })
      .notNull()
      .references(() => detectionRules.id, { onDelete: 'cascade' }),
    hostId: char('host_id', { length: 36 })
      .notNull()
      .references(() => hosts.id, { onDelete: 'restrict' }),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    // Composite PK forbids duplicates and serves the rule FK (leftmost column).
    primaryKey({ name: 'detection_rule_targets_pk', columns: [table.detectionRuleId, table.hostId] }),
    // Serves the host FK and "is this host targeted?" lookups.
    index('detection_rule_targets_host_idx').on(table.hostId),
  ],
);

/**
 * Security incidents registered manually (ADR-025). `status` follows the
 * domain lifecycle (ADR-026); `resolved_at` is set only while RESOLVED or
 * CLOSED. `origin` = DETECTION_ENGINE is reserved: nothing writes it yet.
 */
export const incidents = mysqlTable(
  'incidents',
  {
    id: char('id', { length: 36 }).primaryKey(),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    title: varchar('title', { length: 160 }).notNull(),
    // Plain text up to 5000 characters (enforced by the domain).
    description: text('description'),
    severity: mysqlEnum('severity', SEVERITIES).notNull(),
    status: mysqlEnum('status', INCIDENT_STATUSES).notNull(),
    origin: mysqlEnum('origin', INCIDENT_ORIGINS).notNull(),
    ...timestamps,
    resolvedAt: datetime('resolved_at', { mode: 'date', fsp: 3 }),
  },
  (table) => [
    // Serves the workspace FK and the paginated list (WHERE workspace_id = ? ORDER BY created_at DESC, id DESC).
    index('incidents_workspace_created_idx').on(table.workspaceId, table.createdAt, table.id),
    // Serves the status filter (the main triage filter) with the same ordering.
    index('incidents_workspace_status_created_idx').on(table.workspaceId, table.status, table.createdAt, table.id),
  ],
);

/**
 * Incident ↔ Host (N:N, ADR-024): an incident involves at least one host.
 * Deleting an incident cascades; deleting an involved host is restricted (the
 * application answers 409). Same-workspace consistency is enforced by the
 * application inside the transaction that writes the relations.
 */
export const incidentHosts = mysqlTable(
  'incident_hosts',
  {
    incidentId: char('incident_id', { length: 36 })
      .notNull()
      .references(() => incidents.id, { onDelete: 'cascade' }),
    hostId: char('host_id', { length: 36 })
      .notNull()
      .references(() => hosts.id, { onDelete: 'restrict' }),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    // Composite PK forbids duplicates and serves the incident FK (leftmost column).
    primaryKey({ name: 'incident_hosts_pk', columns: [table.incidentId, table.hostId] }),
    // Serves the host FK and "is this host involved in an incident?" lookups.
    index('incident_hosts_host_idx').on(table.hostId),
  ],
);

/** Incident ↔ Detection Rule (N:N, optional, chosen by hand). Same delete policy as hosts. */
export const incidentDetectionRules = mysqlTable(
  'incident_detection_rules',
  {
    incidentId: char('incident_id', { length: 36 })
      .notNull()
      .references(() => incidents.id, { onDelete: 'cascade' }),
    detectionRuleId: char('detection_rule_id', { length: 36 })
      .notNull()
      .references(() => detectionRules.id, { onDelete: 'restrict' }),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    primaryKey({ name: 'incident_detection_rules_pk', columns: [table.incidentId, table.detectionRuleId] }),
    // Serves the rule FK and "is this rule related to an incident?" lookups.
    index('incident_detection_rules_rule_idx').on(table.detectionRuleId),
  ],
);

/**
 * Human investigations grouping incidents (ADR-028). `status` follows the
 * domain lifecycle (ADR-029): `closed_at` is set only once CLOSED, which
 * requires a `conclusion` and is final.
 */
export const investigations = mysqlTable(
  'investigations',
  {
    id: char('id', { length: 36 }).primaryKey(),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    title: varchar('title', { length: 160 }).notNull(),
    // Plain text up to 5000 / 10000 characters (enforced by the domain).
    description: text('description'),
    conclusion: text('conclusion'),
    status: mysqlEnum('status', INVESTIGATION_STATUSES).notNull(),
    ...timestamps,
    closedAt: datetime('closed_at', { mode: 'date', fsp: 3 }),
  },
  (table) => [
    // Serves the workspace FK and the paginated list (WHERE workspace_id = ? ORDER BY created_at DESC, id DESC).
    index('investigations_workspace_created_idx').on(table.workspaceId, table.createdAt, table.id),
    // Serves the status filter with the same ordering.
    index('investigations_workspace_status_created_idx').on(table.workspaceId, table.status, table.createdAt, table.id),
  ],
);

/**
 * Investigation ↔ Incident (N:N, ADR-028): an investigation groups at least
 * one incident, and an incident may be analysed by several investigations.
 * Deleting an investigation cascades; deleting a grouped incident is
 * restricted (the application answers 409, ADR-030). Same-workspace
 * consistency is enforced by the application inside the transaction that
 * writes the relations.
 */
export const investigationIncidents = mysqlTable(
  'investigation_incidents',
  {
    investigationId: char('investigation_id', { length: 36 })
      .notNull()
      .references(() => investigations.id, { onDelete: 'cascade' }),
    incidentId: char('incident_id', { length: 36 })
      .notNull()
      .references(() => incidents.id, { onDelete: 'restrict' }),
    createdAt: timestamps.createdAt,
  },
  (table) => [
    // Composite PK forbids duplicates and serves the investigation FK (leftmost column).
    primaryKey({ name: 'investigation_incidents_pk', columns: [table.investigationId, table.incidentId] }),
    // Serves the incident FK and "is this incident under investigation?" lookups.
    index('investigation_incidents_incident_idx').on(table.incidentId),
  ],
);

/**
 * Event Store (ADR-032–036): immutable, normalized telemetry facts. `payload`
 * holds exactly the validated `data` of the Event Contract (never the raw
 * request). `(host_id, source_event_id)` makes ingestion idempotent;
 * `fingerprint` (SHA-256 of the canonical event) tells an identical replay
 * from a conflicting reuse. Deleting a workspace cascades; a host with events
 * is protected (RESTRICT → 409), so telemetry is never dropped silently.
 */
export const events = mysqlTable(
  'events',
  {
    id: char('id', { length: 36 }).primaryKey(),
    workspaceId: char('workspace_id', { length: 36 })
      .notNull()
      .references(() => workspaces.id, { onDelete: 'cascade' }),
    hostId: char('host_id', { length: 36 })
      .notNull()
      .references(() => hosts.id, { onDelete: 'restrict' }),
    sourceEventId: char('source_event_id', { length: 36 }).notNull(),
    schemaVersion: smallint('schema_version', { unsigned: true }).notNull(),
    category: mysqlEnum('category', EVENT_CATEGORIES).notNull(),
    eventType: mysqlEnum('event_type', EVENT_TYPES).notNull(),
    occurredAt: datetime('occurred_at', { mode: 'date', fsp: 3 }).notNull(),
    ingestedAt: datetime('ingested_at', { mode: 'date', fsp: 3 }).notNull(),
    payload: json('payload').$type<EventBodyV1['data']>().notNull(),
    fingerprint: char('fingerprint', { length: 64 }).notNull(),
  },
  (table) => [
    // Idempotency key; also serves the host FK and "does this host have events?" lookups.
    uniqueIndex('events_host_source_unique').on(table.hostId, table.sourceEventId),
    // Timeline of the workspace (WHERE workspace_id = ? ORDER BY occurred_at DESC, id DESC).
    index('events_workspace_occurred_idx').on(table.workspaceId, table.occurredAt, table.id),
    // Same timeline filtered by host or by category (event types imply their category).
    index('events_workspace_host_occurred_idx').on(table.workspaceId, table.hostId, table.occurredAt, table.id),
    index('events_workspace_category_occurred_idx').on(table.workspaceId, table.category, table.occurredAt, table.id),
  ],
);
